using System;using System.Text;using UnityEngine;using UnityEngine.InputSystem;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckPoker {
public sealed class PokerMatch:SportsEventSession {
 public PokerPresentation presentation;public SportsEventCamera broadcast;public SportsEventCamera[] seats;public Transform[] cabAnchors,avatars;public SportsCabLook[] looks;public int startingStack=1000,smallBlind=10,levelHands=6;
 public PokerTable Table{get;private set;}public int Version{get;private set;}public bool Handoff{get;private set;}public int Selected{get;private set;}=1;public int RaiseTotal{get;private set;}public string Notice{get;private set;}="";public float Age{get;private set;}public int HumanViews{get;private set;}public readonly int[] ViewOwners={-1,-1,-1,-1};public readonly string[] PublicAction=new string[8];public int ActionsTaken{get;private set;}
 readonly StringBuilder text=new StringBuilder(1200);readonly System.Random[] brains=new System.Random[8];readonly bool[] peekArmed=new bool[8];readonly int[] peekDevice=new int[8];float delay,navWait,rangeWait,awardAge;int lastActionFrame=-1,actor=-1,mouseOwner=-1;bool horizontalReleased=true;const string ConfigKey="TruckPoker.Options.v1";
 [Serializable]sealed class Options{public int stack=1000,blind=10,level=6;}
 public bool HotSeat=>option==1;public override string Title=>"TRUCK POKER";public override int MinimumPlayers=>2;public override int MaximumPlayers=>8;public override int OptionCount=>2;public override int WeatherCount=>1;public override bool MultiViewHUD=>HumanViews>0;public override string OptionLabel=>(HotSeat?"HOT SEAT · PRIVATE HANDOFF":"SIMULTANEOUS · UP TO FOUR VIEWS")+" · TOURNAMENT";
 public override string SourcePolicy=>"Virtual chips only. Whole pad: one owner; shared sticks: separate owners.\nHot seat permits shared sources; split mode uses at most four humans. Hold your assigned peek input to see only your own hand.";
 public override string Help=>"NO-LIMIT HOLD'EM · VIRTUAL CHIPS ONLY\nTwo private cards each, five public board cards. Best five of seven wins. Fold, check/call, or raise to a total. The button and blinds rotate, heads-up button is small blind and acts first before the flop; the big blind acts first afterward. Blinds grow every selected number of hands. Tournament ends when one seat holds all chips.\n\nYOUR CONTROLS\nLeft/right selects FOLD, CHECK/CALL or RAISE. Forward/back adjusts the raise total. Your assigned ACTION freshly confirms. MIN / HALF POT / POT / ALL IN presets select an amount; they never bet without confirmation. Only legal raises are accepted. A short all-in may not reopen raising; the panel explains why. Side pots, splits, odd chips left of the button and uncalled returns are automatic. No real money or online services.\n\nPRIVATE HANDS\nHold your shown PEEK key, whole-pad LEFT SHOULDER or the assigned shared-stick click. Release hides and clears that private display. Your own pane only; no private faces in the world, reflections, logs or replays. Pausing, focus loss, disconnects, folding and handoffs hide private cards. Hot seat requires a fresh handoff confirmation before peeking. Ordinary showdown shows required winners; all-in showdown shows surviving hands. Local split-screen cannot prevent someone physically looking at your pane.\n\nCAB LOOK\nWhole-pad right stick, or hold right mouse for the one keyboard participant assigned the mouse. Middle mouse / whole-pad right-stick click recenters. Separate shared sticks keep fixed useful views. Look never drives or bets. Camera sensitivity/invert are configurable. Public expressions react to actions/results, never hidden hand strength. AI sees only its own hand and public information. Offline names/colors/sources and setup persist through rematches.";
 protected override void Awake(){base.Awake();try{if(SportsPrefs.HasKey(ConfigKey)){var o=JsonUtility.FromJson<Options>(SportsPrefs.GetString(ConfigKey));if(o!=null){startingStack=Mathf.Clamp(o.stack,200,5000);smallBlind=Mathf.Clamp(o.blind,5,100);levelHands=Mathf.Clamp(o.level,3,12);}}}catch(Exception){Debug.LogWarning("Poker options invalid; defaults retained");}SportsLookOptions.Load();}
 public override void NormalizeSetup(){base.NormalizeSetup();setup.mode=HotSeat?BowlingMode.HotSeat:BowlingMode.Simultaneous;setup.sharedHotSeat=HotSeat;}
 static readonly Key[] peekKeys={Key.E,Key.RightCtrl,Key.Y,Key.O,Key.N,Key.NumpadPeriod,Key.Digit9,Key.Insert};
 public Key PeekKey(int slot){return peekKeys[Mathf.Clamp(KeyboardCluster(slot)-1,0,7)];}
 public string PeekCaption(int slot){var p=setup.players[slot];return p.source==BowlingSource.Keyboard?PeekKey(slot).ToString().ToUpperInvariant():p.source==BowlingSource.WholeController?"LB":p.source==BowlingSource.LeftStick?"LEFT STICK CLICK":p.source==BowlingSource.RightStick?"RIGHT STICK CLICK":"AI";}
 public override string ControlCaption(int slot)=>Controls(slot)+(setup.players[slot].source==BowlingSource.AI?"":" · HOLD "+PeekCaption(slot)+" PEEK");
 public override bool ValidateSources(out string reason){if(!base.ValidateSources(out reason))return false;int humans=0;for(int i=0;i<setup.count;i++){var p=setup.players[i];if(p.source!=BowlingSource.AI)humans++;if(p.source!=BowlingSource.Keyboard)continue;var key=PeekKey(i);for(int j=0;j<setup.count;j++){var q=setup.players[j];if(q.source!=BowlingSource.Keyboard||HotSeat&&i!=j)continue;if(key==q.forward||key==q.left||key==q.back||key==q.right||key==actionKeys[j]||i!=j&&key==PeekKey(j)){reason="Peek source overlaps slot "+(j+1)+". Choose separate keyboard clusters.";return false;}}}if(!HotSeat&&humans>4){reason="Use hot seat for more than four humans.";return false;}return true;}
 public override string Header=>Title+" · HAND "+(Table==null?0:Table.HandNumber)+" · BLINDS "+(Table==null?smallBlind:Table.SmallBlind)+" / "+(Table==null?smallBlind*2:Table.BigBlind);
 public override string Status=>Table==null?"VIRTUAL CHIPS · OFFLINE":Table.HandDone?"POTS AWARDED · NEXT HAND SHORTLY":Handoff?"PASS TO "+setup.players[Table.Actor].name+" · RELEASE, THEN ACTION":"ACTION: "+setup.players[Table.Actor].name+" · "+Table.Street.ToString().ToUpperInvariant()+" · POT "+Table.Pot;
 public override string Standings{get{text.Clear();for(int i=0;i<setup.count;i++)text.Append(setup.players[i].name).Append("  ").Append(Table==null?startingStack:Table.Stack(i)).Append(" CHIPS · ").Append(Table==null?"READY":Table.Stack(i)==0&&(Table.HandDone||!Table.IsInHand(i))?"OUT":PublicAction[i]??"WAITING").Append('\n');return text.ToString();}}
 public override string Results=>(Table!=null&&Table.Winner>=0?setup.players[Table.Winner].name+" WINS THE TABLE":"TABLE COMPLETE")+"\n\n"+Standings;
 public override void RefreshExtraUI(){if(presentation!=null)presentation.Options();}
 public override string ViewText(int view){int owner=ViewOwners[view];return owner<0?Header+"\n"+Status:"<color=#"+ColorUtility.ToHtmlStringRGB(setup.players[owner].color)+">"+setup.players[owner].name+"</color> · "+Table.Stack(owner)+" CHIPS\n"+Status+"\n"+(Table.IsFolded(owner)?"FOLDED":Table.HandDone?"HAND COMPLETE":"HOLD "+PeekCaption(owner)+" TO PEEK");}
 protected override void BeginGame(){presentation.ClearPrivate();int[] stacks=new int[setup.count];for(int i=0;i<setup.count;i++){stacks[i]=startingStack;brains[i]=new System.Random(Guid.NewGuid().GetHashCode());PublicAction[i]="READY";}Table=new PokerTable(stacks,Guid.NewGuid().GetHashCode(),smallBlind,levelHands);Age=0;ActionsTaken=0;Version=0;actor=-1;mouseOwner=-1;for(int i=0;i<setup.count;i++)if(setup.players[i].source==BowlingSource.Keyboard){mouseOwner=i;break;}presentation.ResetTable();NextHand();}
 void NextHand(){ClearPeekGate();presentation.ClearPrivate();foreach(var look in looks)look.ResetLook();if(!Table.BeginHand()){EndMatch();return;}for(int i=0;i<setup.count;i++)PublicAction[i]=Table.Stack(i)==0&&!Table.IsInHand(i)?"OUT":"WAITING";Version++;awardAge=0;delay=.85f;actor=-1;ActorChanged();Layout();presentation.PublicStateChanged();if(Table.HandDone)presentation.Award();}
 void ActorChanged(){if(Table.HandDone){Handoff=false;actor=-1;presentation.ClearPrivate();return;}int next=Table.Actor;if(next==actor)return;actor=next;Handoff=HotSeat&&setup.players[actor].source!=BowlingSource.AI;if(Handoff)ClearPeekGate();Selected=1;var v=Table.View(actor);RaiseTotal=Math.Min(v.MaximumRaiseTo,v.MinimumRaiseTo);Notice="";horizontalReleased=true;navWait=rangeWait=0;presentation.ClearPrivate();Gate();if(HotSeat)Layout();}
 void Layout(){HumanViews=0;for(int i=0;i<4;i++)ViewOwners[i]=-1;if(HotSeat){if(!Table.HandDone&&setup.players[Table.Actor].source!=BowlingSource.AI){HumanViews=1;ViewOwners[0]=Table.Actor;}}else for(int i=0;i<setup.count;i++)if(setup.players[i].source!=BowlingSource.AI)ViewOwners[HumanViews++]=i;broadcast.view.enabled=HumanViews==0;for(int i=0;i<4;i++){seats[i].view.enabled=i<HumanViews;if(i<HumanViews)seats[i].view.rect=LWS.TruckCornhole.CornholeMatch.ViewRect(HumanViews,i);}cameras=HumanViews==0?new[]{broadcast.view}:new Camera[HumanViews];for(int i=0;i<HumanViews;i++)cameras[i]=seats[i].view;presentation.Layout();}
 protected override void Simulate(float dt){if(Table==null)return;Age+=dt;delay=Mathf.Max(0,delay-dt);if(Table.HandDone){awardAge+=dt;if(awardAge>=2.7f){if(Table.Winner>=0)EndMatch();else NextHand();}return;}if(actor!=Table.Actor)ActorChanged();if(delay>0)return;int seat=Table.Actor;if(setup.players[seat].source==BowlingSource.AI){var move=PokerPolicy.Choose(Table.View(seat),(int)setup.players[seat].difficulty,brains[seat]);Commit(seat,move.Action,move.Total);return;}if(Handoff){if(actions[seat]){Handoff=false;presentation.ClearPrivate();Gate();delay=.15f;}return;}var drive=commands[seat];navWait=Mathf.Max(0,navWait-dt);rangeWait=Mathf.Max(0,rangeWait-dt);if(Mathf.Abs(drive.x)<.2f)horizontalReleased=true;if(Mathf.Abs(drive.x)>.55f&&horizontalReleased&&navWait<=0){Selected=(Selected+(drive.x>0?1:2))%3;horizontalReleased=false;navWait=.15f;}if(Selected==2&&Mathf.Abs(drive.y)>.45f&&rangeWait<=0){var v=Table.View(seat);int min=Math.Min(v.MinimumRaiseTo,v.MaximumRaiseTo);RaiseTotal=Mathf.Clamp(RaiseTotal+(drive.y>0?1:-1)*Math.Max(1,Table.BigBlind/5),min,v.MaximumRaiseTo);rangeWait=.09f;}if(actions[seat])Confirm(seat);}
 public bool MouseOwns(int view)=>Table!=null&&!Table.HandDone&&view>=0&&view<HumanViews&&ViewOwners[view]==Table.Actor&&(HotSeat||Table.Actor==mouseOwner)&&setup.players[Table.Actor].source==BowlingSource.Keyboard;
 public void MouseRaise(int view,int total){if(!Live||Handoff||delay>0||!MouseOwns(view)||Mouse.current==null||!Mouse.current.leftButton.isPressed)return;var v=Table.View(Table.Actor);Selected=2;RaiseTotal=Mathf.Clamp(total,Math.Min(v.MinimumRaiseTo,v.MaximumRaiseTo),v.MaximumRaiseTo);}
 void Confirm(int seat){if(Handoff||delay>0||Table.HandDone||seat!=Table.Actor)return;if(Selected==2&&!Table.RaiseAllowed(seat,out var reason)){Notice=reason;feedback.Play(3,0,true);return;}Commit(seat,Selected==0?PokerAction.Fold:Selected==1?PokerAction.CheckCall:PokerAction.RaiseTo,RaiseTotal);}
 bool Commit(int seat,PokerAction action,int total){if(!Live||lastActionFrame==Time.frameCount)return false;var prior=Table.Street;if(!Table.Act(seat,action,total,out var reason)){Notice=reason;return false;}lastActionFrame=Time.frameCount;ActionsTaken++;PublicAction[seat]=action==PokerAction.Fold?"FOLD":action==PokerAction.RaiseTo?"RAISE TO "+total:"CHECK / CALL";presentation.ClearPrivate();presentation.React(seat,action);feedback.Play(action==PokerAction.Fold?1:2,0,true);Pulse(seat,.12f,.07f);Version++;delay=Table.Street!=prior?.85f:Mathf.Lerp(.6f,.3f,(int)setup.players[seat].difficulty*.5f);ActorChanged();presentation.PublicStateChanged();if(Table.HandDone){awardAge=0;Layout();presentation.Award();}return true;}
 public bool PeekAllowed(int seat){bool focused=Application.isFocused;
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 focused|=SportsProbeInputIsolation.Active;
#endif
 if(!Live||!focused||Table==null||Table.HandDone||Handoff||seat<0||seat>=setup.count||!Ready(seat)||setup.players[seat].source==BowlingSource.AI||!Table.IsInHand(seat)||Table.IsFolded(seat)||HotSeat&&seat!=Table.Actor)return false;for(int i=0;i<HumanViews;i++)if(ViewOwners[i]==seat&&seats[i].view.enabled)return true;return false;}
 public void ClearPeekGate(){Array.Clear(peekArmed,0,peekArmed.Length);}
 public bool PeekHeld(int slot){if(!PeekAllowed(slot))return false;var p=setup.players[slot];int device=p.source==BowlingSource.Keyboard?(Keyboard.current!=null?Keyboard.current.deviceId:-1):p.pad!=null?p.pad.deviceId:-1;if(peekDevice[slot]!=device){peekDevice[slot]=device;peekArmed[slot]=false;}bool held=p.source==BowlingSource.Keyboard?SportsDeviceInput.KeyHeld(PeekKey(slot)):p.source==BowlingSource.WholeController?p.pad.leftShoulder.isPressed:p.source==BowlingSource.LeftStick?p.pad.leftStickButton.isPressed:p.pad.rightStickButton.isPressed;if(!peekArmed[slot]){if(!held)peekArmed[slot]=true;return false;}return held;}
 public void MouseAction(int view,int action){if(!Live||Table==null||Table.HandDone||Handoff||delay>0||view<0||view>=HumanViews||ViewOwners[view]!=Table.Actor||(!HotSeat&&Table.Actor!=mouseOwner)||setup.players[Table.Actor].source!=BowlingSource.Keyboard||Mouse.current==null||!Mouse.current.leftButton.wasReleasedThisFrame||!MenuConfirm())return;int seat=Table.Actor;var v=Table.View(seat);if(action<3){Selected=action;Confirm(seat);}else{Selected=2;int requested=action==3?v.MinimumRaiseTo:action==4?Table.CurrentBet+Math.Max(Table.BigBlind,(v.Pot+v.Call)/2):action==5?Table.CurrentBet+Math.Max(Table.BigBlind,v.Pot+v.Call):v.MaximumRaiseTo;RaiseTotal=Mathf.Clamp(requested,Math.Min(v.MinimumRaiseTo,v.MaximumRaiseTo),v.MaximumRaiseTo);}}
 protected override void Present(float dt){if(presentation==null||avatars==null)return;broadcast.Pose(new Vector3(0,1.2f,0),new Vector3(0,14,-17),58);if(Table!=null)for(int i=0;i<HumanViews;i++){int owner=ViewOwners[i];var avatar=avatars[owner];var basis=avatar.rotation*Quaternion.Euler(9,0,0);var position=avatar.position+Vector3.up*1.05f+avatar.rotation*new Vector3(-.25f,0,1.08f);cabAnchors[i].SetPositionAndRotation(position,basis);bool mouse=HotSeat||owner==mouseOwner;var rotation=looks[i].Apply(basis,setup.players[owner],owner,mouse,Live&&!Handoff,SportsLookOptions.Sensitivity,SportsLookOptions.InvertY);seats[i].view.cullingMask=(~(1<<(10+owner)))&~(15<<25)|(1<<(25+i));seats[i].view.transform.SetPositionAndRotation(position,rotation);}presentation.Tick();}
 public override void ExtraAction(string key){if(Running&&!Finished&&key!="pokerlook"&&key!="pokerinvert")return;bool changed=true;if(key=="pokerstack")startingStack=startingStack>=2000?500:startingStack*2;else if(key=="pokerblind")smallBlind=smallBlind>=25?5:smallBlind==5?10:25;else if(key=="pokerlevel")levelHands=levelHands>=9?3:levelHands+3;else if(key=="pokerlook")SportsLookOptions.CycleSensitivity();else if(key=="pokerinvert")SportsLookOptions.Set(SportsLookOptions.Sensitivity,!SportsLookOptions.InvertY);else changed=false;if(changed){SportsPrefs.SetString(ConfigKey,JsonUtility.ToJson(new Options{stack=startingStack,blind=smallBlind,level=levelHands}));SportsPrefs.Save();menus.Dirty();}}
 protected override void SetPaused(bool pause){if(pause){ClearPeekGate();presentation.ClearPrivate();foreach(var look in looks)look.ReleaseCursor();}}
 protected override void StopGame(){ClearPeekGate();if(presentation!=null)presentation.ClearPrivate();if(looks!=null)foreach(var look in looks)if(look!=null)look.ReleaseCursor();if(broadcast!=null)broadcast.view.enabled=true;if(seats!=null)foreach(var seat in seats)seat.view.enabled=false;HumanViews=0;cameras=broadcast!=null?new[]{broadcast.view}:Array.Empty<Camera>();}
}
}
